17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	import java.util.Objects;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.security.access.prepost.PreAuthorize;
41	import org.springframework.web.bind.annotation.CrossOrigin;
42	import org.springframework.web.bind.annotation.RequestMapping;
43	import org.springframework.web.bind.annotation.RestController;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        if (isDuplicateOwner(owner)) {
106	            return new ResponseEntity<>(HttpStatus.CONFLICT);
107	        }
108	        this.clinicService.saveOwner(owner);
109	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
110	        headers.setLocation(UriComponentsBuilder.newInstance()
111	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
112	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
118	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
119	        if (currentOwner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        currentOwner.setAddress(ownerFieldsDto.getAddress());
123	        currentOwner.setCity(ownerFieldsDto.getCity());
124	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
125	        currentOwner.setLastName(ownerFieldsDto.getLastName());
126	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
127	        this.clinicService.saveOwner(currentOwner);
128	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Transactional
133	    @Override
134	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
135	        Owner owner = this.clinicService.findOwnerById(ownerId);
136	        if (owner == null) {
137	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
138	        }
139	        this.clinicService.deleteOwner(owner);
140	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
141	    }
142	
143	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
144	    @Override
145	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
146	        Owner owner = this.clinicService.findOwnerById(ownerId);
147	        if (owner == null) {
148	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
149	        }
150	        HttpHeaders headers = new HttpHeaders();
151	        Pet pet = petMapper.toPet(petFieldsDto);
152	        owner.setId(ownerId);
153	        pet.setOwner(owner);
154	        pet.getType().setName(null);
155	        this.clinicService.savePet(pet);
156	        PetDto petDto = petMapper.toPetDto(pet);
157	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
158	            .buildAndExpand(pet.getId()).toUri());
159	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
165	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
166	        if (currentOwner != null) {
167	            Pet currentPet = this.clinicService.findPetById(petId);
168	            if (currentPet != null) {
169	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
170	                currentPet.setName(petFieldsDto.getName());
171	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
172	                this.clinicService.savePet(currentPet);
173	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
174	            }
175	        }
176	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
182	        HttpHeaders headers = new HttpHeaders();
183	        Visit visit = visitMapper.toVisit(visitFieldsDto);
184	        Pet pet = new Pet();
185	        pet.setId(petId);
186	        visit.setPet(pet);
187	        this.clinicService.saveVisit(visit);
188	        VisitDto visitDto = visitMapper.toVisitDto(visit);
189	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
190	            .buildAndExpand(visit.getId()).toUri());
191	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
192	    }
193	
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
198	        Owner owner = this.clinicService.findOwnerById(ownerId);
199	        if (owner != null) {
200	            Pet pet = owner.getPet(petId);
201	            if (pet != null) {
202	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
203	            }
204	        }
205	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
206	    }
207	
208	    /**
209	     * Determines whether an owner already exists that shares the same last name and telephone
210	     * number as the given candidate.
211	     *
212	     * @param owner the candidate owner to check
213	     * @return {@code true} if an owner with the same last name and telephone already exists
214	     */
215	    private boolean isDuplicateOwner(Owner owner) {
216	        return this.clinicService.findOwnerByLastName(owner.getLastName()).stream()
217	            .anyMatch(existing ->
218	                Objects.equals(existing.getLastName(), owner.getLastName())
219	                    && Objects.equals(existing.getTelephone(), owner.getTelephone()));
220	    }
221	}
